from pathlib import Path
note='''> **Hardware correction — November 6, 2026:** The current toolboard specification is **BTT EBB42**, replacing EBB36. Exact EBB42 revision and MCU are not yet established. Historical EBB36 wiring, connector positions, pin assignments, firmware settings and mounting drawings below are not an approved EBB42 wiring plan; verify against the exact EBB42 documentation before use. The X1C hotend and other established build components remain the current baseline.\n\n'''
for name in ['START_HERE_AD5M.txt','TOOLHEAD_FIRST.md','BUILD_SEQUENCE.md','UPGRADE_ROADMAP.md']:
 p=Path(name);s=p.read_text(encoding='utf-8');p.write_text(note+s,encoding='utf-8')
Path('CURRENT_TOOLHEAD_SPEC.md').write_text('''# Current toolhead specification\n\nUpdated November 6, 2026 by explicit user correction.\n\n- Printer: Flashforge AD5M rebuild.\n- Toolboard: BTT EBB42. Supersedes EBB36 in previous planning.\n- Exact EBB42 revision / MCU: unconfirmed. Do not inherit EBB36 revision V1.2.1.\n- Hotend: standard Bambu X1C, connector changed only, per existing build record.\n- Extruder: AD5M feeder available for reuse; replacement under evaluation.\n- Toolboard bracket: design for the actual EBB42 hole pattern and connector envelope. A compact extruder with a 36 mm motor can still use EBB42 on a separate bracket; board choice does not establish motor compatibility.\n- Wiring / firmware: previous EBB36 assignments require exact-revision EBB42 verification. No EBB42 pin map or flashed firmware is confirmed by this correction.\n- Future direction: XY rails first after restoring printing; four complete interchangeable toolheads later.\n''',encoding='utf-8')
